function filterColor(e){switch(e){case"very easy":return' filter: invert(100%) sepia(187%) saturate(7237%) hue-rotate(274deg) brightness(113%) contrast(119%);" title="Very Easy';case"easy":return' filter: invert(59%) sepia(81%) saturate(391%) hue-rotate(46deg) brightness(97%) contrast(87%);" title="Easy';case"medium":return' filter: invert(5%) sepia(45%) saturate(2974%) hue-rotate(337deg) brightness(99%) contrast(96%);" title="Medium';case"hard":return' filter: invert(1099%) sepia(579%) saturate(4912%) hue-rotate(338deg) brightness(98%) contrast(128%);" title="Hard';case"insane":return' filter: invert(93%) sepia(88%) saturate(0%) hue-rotate(323deg) brightness(91%) contrast(98%);" title="Insane';default:return""}}function formatItem(e){return`<div class="relative w-100 w-30-l mb4 bg-card shadow-hover"><img alt="${e.title}" class="absolute w-20 ml-5 t-50 transform-img" src="${e.image}" style="${filterColor(e.difficulty)}"><div class="relative w-75 ml-25 pa4 overflow-hidden"><span class="f6 db">${e.section.toUpperCase()}</span><h3 class="ellipsis f3"><a class="link dim" href="${e.permalink}" title="${e.title}">${e.title}</a></h3><span>${e.summary}</span></div></div>`}